2	import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
3	import type { Conversation, DestinationCatalog, DestinationPage, MailClient, ProviderDestination } from '../lib/ipc/client';
4	import { toMailError } from '../lib/ipc/client';
5	import FullDate from './FullDate.vue';
6	
7	const props = defineProps<{ client: MailClient; accountId: string }>();
8	const catalog = ref<DestinationCatalog | null>(null);
9	const destination = ref<ProviderDestination | null>(null);
10	const page = ref<DestinationPage | null>(null);
11	const opened = ref<Conversation | null>(null);
12	const query = ref('');
13	const shown = ref(9);
14	const busy = ref(false);
15	const error = ref('');
16	const cached = ref(false);
17	const list = ref<HTMLElement | null>(null);
18	const readerBack = ref<HTMLButtonElement | null>(null);
19	let listScrollTop = 0;
20	let generation = 0;
21	let origin: HTMLElement | null = null;
22	const matches = computed(() => (catalog.value?.destinations ?? []).filter(d => d.name.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())));
23	const visible = computed(() => matches.value.slice(0, shown.value));
24	onBeforeUnmount(() => { generation += 1; });
25	
26	async function loadCatalog(useCache = false) {
27	  const token = ++generation;
28	  busy.value = true; error.value = '';
29	  try {
30	    const result = await props.client.listProviderDestinations(props.accountId, useCache);
31	    if (token !== generation || result.accountId !== props.accountId) return;
32	    catalog.value = result; cached.value = useCache;
33	  } catch (e) { if (token === generation) error.value = toMailError(e).kind; }
34	  finally { if (token === generation) busy.value = false; }
35	}
36	async function loadPage(target: ProviderDestination, cursor: string | null = null, useCache = false) {
37	  const token = ++generation;
38	  busy.value = true; error.value = ''; opened.value = null;
39	  if (destination.value?.id !== target.id) page.value = null;
40	  destination.value = target;
41	  try {
42	    const result = await props.client.browseProviderDestination({ accountId: props.accountId, destinationId: target.id, cursor, cached: useCache });
43	    if (token !== generation || result.accountId !== props.accountId || result.destinationId !== target.id) return;
44	    page.value = result; cached.value = useCache;
45	    await nextTick(); list.value?.focus();
46	  } catch (e) { if (token === generation) error.value = toMailError(e).kind; }
47	  finally { if (token === generation) busy.value = false; }
48	}
49	function open(conversation: Conversation, event: Event) {
50	  // A pending Refresh/Next will replace this page and disconnect the clicked
51	  // row: opening during the wait would strand the reader on a dead origin.
52	  if (busy.value) return;
53	  origin = event.currentTarget as HTMLElement;
54	  listScrollTop = list.value?.scrollTop ?? 0;
55	  opened.value = conversation;
56	  void nextTick(() => readerBack.value?.focus());
57	}
58	async function backToList() {
59	  opened.value = null;
60	  await nextTick();
61	  if (list.value) list.value.scrollTop = listScrollTop;
62	  if (origin?.isConnected) origin.focus({ preventScroll: true });
63	}
64	function backToCatalog() {
65	  generation += 1; busy.value = false; error.value = ''; destination.value = null; page.value = null;
66	}
67	function keydown(event: KeyboardEvent) {
68	  // The native palette binding must reach App's window handler even when focus
69	  // sits inside this drawer; ordinary keys stay fenced off the covered inbox.
70	  // Browser reservations and IME composition are left untouched (no
71	  // preventDefault outside the reader Escape below).
72	  if (event.key === 'Escape' && (event.isComposing || event.keyCode === 229
73	    || event.ctrlKey || event.metaKey || event.altKey)) return;
74	  const nativePaletteKey = event.metaKey && !event.ctrlKey && !event.altKey && !event.shiftKey
75	    && event.key.toLowerCase() === 'k' && !event.isComposing && event.keyCode !== 229;
76	  if (event.key === 'Escape' && opened.value) { event.preventDefault(); void backToList(); event.stopPropagation(); }
77	  else if (event.key !== 'Escape' && !nativePaletteKey) event.stopPropagation();
78	}
79	onMounted(() => { void loadCatalog(); });
80	</script>
